package com.rewind;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class RewindPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(RewindPlugin.class);
		RuneLite.main(args);
	}
}

package com.rewind.regionlocker;

import java.awt.Canvas;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.lang.reflect.Proxy;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import org.junit.Test;
import static org.junit.Assert.*;

public class HistoricalMinimapInputBlockerTest
{
    private final Canvas canvas = new Canvas();

    private MouseEvent event(int id, int x, int y, int button)
    {
        return new MouseEvent(canvas, id, 0, 0, x, y, 1, false, button);
    }

    private HistoricalMinimapInputBlocker blocker()
    {
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
            new Class<?>[]{Client.class}, (p, m, a) -> {
                throw new AssertionError("Mouse callback accessed live client: " + m.getName());
            });
        HistoricalMinimapInputBlocker blocker = new HistoricalMinimapInputBlocker(client);
        blocker.publish(new HistoricalMinimapInputBlocker.Snapshot(new Rectangle(600, 0, 150, 150),
            new HistoricalMinimapInputBlocker.TilePoint[]{
                new HistoricalMinimapInputBlocker.TilePoint(675, 75, true),
                new HistoricalMinimapInputBlocker.TilePoint(690, 75, false)}));
        return blocker;
    }

    private void sequence(HistoricalMinimapInputBlocker blocker, int x, int y, int button, boolean consumed)
    {
        MouseEvent press = event(MouseEvent.MOUSE_PRESSED, x, y, button);
        MouseEvent release = event(MouseEvent.MOUSE_RELEASED, x, y, button);
        MouseEvent click = event(MouseEvent.MOUSE_CLICKED, x, y, button);
        assertSame(press, blocker.mousePressed(press));
        assertSame(release, blocker.mouseReleased(release));
        assertSame(click, blocker.mouseClicked(click));
        assertEquals(consumed, press.isConsumed());
        assertEquals(consumed, release.isConsumed());
        assertEquals(consumed, click.isConsumed());
    }

    @Test public void normalGameAndUiClicksNeverReadClientFromAwt() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            HistoricalMinimapInputBlocker b = blocker();
            sequence(b, 200, 200, MouseEvent.BUTTON1, false);
            sequence(b, 700, 400, MouseEvent.BUTTON1, false);
            sequence(b, 601, 1, MouseEvent.BUTTON1, false); // outside circular minimap
            sequence(b, 690, 75, MouseEvent.BUTTON1, false); // unlocked tile
            sequence(b, 675, 75, MouseEvent.BUTTON3, false);
            sequence(b, 675, 75, MouseEvent.BUTTON2, false);
        });
    }

    @Test public void lockedLeftSequenceIsConsumedAndNextOrdinaryClickPasses() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            HistoricalMinimapInputBlocker b = blocker();
            sequence(b, 675, 75, MouseEvent.BUTTON1, true);
            sequence(b, 200, 200, MouseEvent.BUTTON1, false);
        });
    }

    @Test public void unmatchedMinimapClickPasses()
    {
        sequence(blocker(), 675, 110, MouseEvent.BUTTON1, false);
    }

    @Test public void missingSnapshotPasses()
    {
        HistoricalMinimapInputBlocker b = blocker();
        b.clear();
        sequence(b, 675, 75, MouseEvent.BUTTON1, false);
    }

    @Test public void consumedPressDoesNotStartBlockedSequence()
    {
        HistoricalMinimapInputBlocker b = blocker();
        MouseEvent press = event(MouseEvent.MOUSE_PRESSED, 675, 75, MouseEvent.BUTTON1);
        press.consume();
        assertSame(press, b.mousePressed(press));
        MouseEvent release = event(MouseEvent.MOUSE_RELEASED, 675, 75, MouseEvent.BUTTON1);
        assertFalse(b.mouseReleased(release).isConsumed());
    }

    @Test public void dragWithoutClickCannotPoisonNextPress()
    {
        HistoricalMinimapInputBlocker b = blocker();
        assertTrue(b.mousePressed(event(MouseEvent.MOUSE_PRESSED, 675, 75, MouseEvent.BUTTON1)).isConsumed());
        assertTrue(b.mouseReleased(event(MouseEvent.MOUSE_RELEASED, 200, 200, MouseEvent.BUTTON1)).isConsumed());
        sequence(b, 200, 200, MouseEvent.BUTTON1, false);
    }

    @Test public void motionAndBoundaryEventsPassThrough()
    {
        HistoricalMinimapInputBlocker b = blocker();
        MouseEvent motion = event(MouseEvent.MOUSE_MOVED, 675, 75, MouseEvent.NOBUTTON);
        assertSame(motion, b.mouseMoved(motion));
        assertSame(motion, b.mouseDragged(motion));
        assertSame(motion, b.mouseEntered(motion));
        assertSame(motion, b.mouseExited(motion));
        assertFalse(motion.isConsumed());
    }

    @Test public void logoutAndContextMenuClearCachedBlocking()
    {
        for (boolean menu : new boolean[]{false, true})
        {
            Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
                new Class<?>[]{Client.class}, (p, m, a) -> {
                    if (m.getName().equals("getGameState")) return menu ? GameState.LOGGED_IN : GameState.LOGIN_SCREEN;
                    if (m.getName().equals("isMenuOpen")) return menu;
                    throw new AssertionError("Unexpected read: " + m.getName());
                });
            HistoricalMinimapInputBlocker b = new HistoricalMinimapInputBlocker(client);
            b.publish(new HistoricalMinimapInputBlocker.Snapshot(new Rectangle(600, 0, 150, 150),
                new HistoricalMinimapInputBlocker.TilePoint[]{new HistoricalMinimapInputBlocker.TilePoint(675, 75, true)}));
            b.refresh();
            sequence(b, 675, 75, MouseEvent.BUTTON1, false);
        }
    }

    private static <T> T proxy(Class<T> type, java.util.Map<String, Object> values)
    {
        return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, (p, m, a) -> {
            if (SwingUtilities.isEventDispatchThread()) throw new AssertionError("Live game access on AWT");
            if (values.containsKey(m.getName())) return values.get(m.getName());
            throw new AssertionError("Unexpected game method: " + m.getName());
        }));
    }

    @Test public void projectedLockedTilesAndGeOverrideWorkInAllLayouts() throws Exception
    {
        for (int layout = 0; layout < 3; layout++)
        {
            net.runelite.api.coords.LocalPoint local = new net.runelite.api.coords.LocalPoint(64, 64, net.runelite.api.WorldView.TOPLEVEL);
            net.runelite.api.Scene scene = proxy(net.runelite.api.Scene.class, java.util.Map.of(
                "isInstance", false, "getBaseX", 3136, "getBaseY", 3456)); // GE region 12598
            net.runelite.api.WorldView view = proxy(net.runelite.api.WorldView.class, java.util.Map.of(
                "getId", net.runelite.api.WorldView.TOPLEVEL, "getSizeX", 1, "getSizeY", 1, "getPlane", 0, "getScene", scene));
            net.runelite.api.Player player = proxy(net.runelite.api.Player.class, java.util.Map.of(
                "getWorldView", view, "getLocalLocation", local, "getCameraFocus", local));
            java.util.Map<String, Object> widgetValues = new java.util.HashMap<>();
            widgetValues.put("isHidden", false);
            widgetValues.put("getBounds", new Rectangle(600, 0, 150, 150));
            widgetValues.put("getCanvasLocation", new net.runelite.api.Point(600, 0));
            widgetValues.put("getWidth", 150);
            widgetValues.put("getHeight", 150);
            net.runelite.api.widgets.Widget widget = proxy(net.runelite.api.widgets.Widget.class, widgetValues);
            java.util.Map<String, Object> values = new java.util.HashMap<>();
            values.put("getGameState", GameState.LOGGED_IN);
            values.put("isMenuOpen", false);
            values.put("isResized", layout != 0);
            values.put("getVarbitValue", layout == 1 ? 1 : 0);
            values.put("getWidget", widget);
            values.put("getLocalPlayer", player);
            values.put("getCameraFocusEntity", player);
            values.put("getMinimapZoom", 4.0);
            values.put("getCameraYawTarget", 0);
            HistoricalMinimapInputBlocker b = new HistoricalMinimapInputBlocker(proxy(Client.class, values));
            HistoricalRegionState.replaceWith(java.util.Collections.emptyList());
            HistoricalRegionState.setAdditionallyUnlocked(java.util.Collections.emptyList());
            b.refresh();
            SwingUtilities.invokeAndWait(() -> sequence(b, 675, 75, MouseEvent.BUTTON1, true));
            HistoricalRegionState.setAdditionallyUnlocked(java.util.Collections.singleton(12598));
            b.refresh();
            SwingUtilities.invokeAndWait(() -> sequence(b, 675, 75, MouseEvent.BUTTON1, false));
            HistoricalRegionState.setAdditionallyUnlocked(java.util.Collections.emptyList());
            widgetValues.put("isHidden", true);
            b.refresh();
            sequence(b, 675, 75, MouseEvent.BUTTON1, false);
        }
    }
}

package com.rewind;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Skill;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import org.junit.BeforeClass;
import org.junit.Test;
import static org.junit.Assert.*;

public class RewindOverlayTest
{
    @BeforeClass
    public static void load() throws Exception
    {
        HistoricalDataTest.load();
    }

    private static <T> T proxy(Class<T> type, Map<String, Object> values)
    {
        return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, (p, m, a) -> {
            if (m.getName().equals("hashCode")) return System.identityHashCode(p);
            if (m.getName().equals("equals")) return p == a[0];
            if (values.containsKey(m.getName())) return values.get(m.getName());
            if (m.getReturnType() == boolean.class) return false;
            if (m.getReturnType() == int.class) return -1;
            return null;
        }));
    }

    @Test
    public void itemOverlayUsesRuneLiteWidgetItemOverlay()
    {
        assertTrue(WidgetItemOverlay.class.isAssignableFrom(RewindItemOverlay.class));
    }

    @Test
    public void lockedMaskPaintsTheRequestedBounds()
    {
        BufferedImage image = new BufferedImage(100, 100, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        try
        {
            RewindItemOverlay.paintLocked(graphics, new Rectangle(10, 10, 36, 32));
        }
        finally
        {
            graphics.dispose();
        }

        assertNotEquals(0, image.getRGB(20, 20));
        assertEquals(0, image.getRGB(2, 2));
    }

    @Test
    public void skillWidgetsResolveByLiveGuideAction()
    {
        for (Skill skill : new Skill[]{Skill.FARMING, Skill.CONSTRUCTION, Skill.HUNTER, Skill.SAILING})
        {
            Map<String, Object> values = new HashMap<>();
            values.put("getActions", new String[]{"View " + skill.getName() + " guide"});
            Widget widget = proxy(Widget.class, values);
            assertEquals(skill, RewindSkillOverlay.skillForWidget(widget));
        }

        Widget unrelated = proxy(Widget.class, Map.of("getActions", new String[]{"Configure"}));
        assertNull(RewindSkillOverlay.skillForWidget(unrelated));
    }

    @Test
    public void sailingIsAlwaysPermanentlyLocked()
    {
        assertTrue(HistoricalPermanentExclusions.isSkillPermanentlyLocked(Skill.SAILING));
        assertFalse(HistoricalPermanentExclusions.isSkillPermanentlyLocked(Skill.FARMING));
        assertFalse(HistoricalPermanentExclusions.isSkillPermanentlyLocked(Skill.CONSTRUCTION));
        assertFalse(HistoricalPermanentExclusions.isSkillPermanentlyLocked(Skill.HUNTER));
    }

    @Test
    public void finalHistoricalReleaseContainsFarmingConstructionAndHunterButNotSailing()
    {
        Release latest = Release.getRELEASES().get(Release.getRELEASES().size() - 1);
        assertTrue(Release.getSkills(latest).contains(Skill.FARMING));
        assertTrue(Release.getSkills(latest).contains(Skill.CONSTRUCTION));
        assertTrue(Release.getSkills(latest).contains(Skill.HUNTER));
        assertFalse(Release.getSkills(latest).contains(Skill.SAILING));
    }
}

package com.rewind;

import com.rewind.regionlocker.HistoricalRegionState;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.*;
import java.util.stream.Collectors;
import net.runelite.api.Quest;
import net.runelite.api.Prayer;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InterfaceID;
import org.junit.BeforeClass;
import org.junit.Test;
import static org.junit.Assert.*;

public class HistoricalDataTest {
    private static final Gson GSON = new Gson();
    private static Map<Quest, LocalDate> expectedQuests = new HashMap<>();
    private static Reader resource(String name) {
        return new InputStreamReader(Objects.requireNonNull(HistoricalDataTest.class.getResourceAsStream(name)), StandardCharsets.UTF_8);
    }
    private static Date date(String value) {
        return Date.from(LocalDate.parse(value).atStartOfDay(ZoneId.systemDefault()).toInstant());
    }
    private static Release release(String value) {
        return Release.getRELEASES().stream().filter(r -> r.getDate().getLocalDate().equals(LocalDate.parse(value)))
            .findFirst().orElseThrow(AssertionError::new);
    }
    @BeforeClass public static void load() throws Exception {
        List<Release> releases = new ArrayList<>();
        for (String file : Arrays.asList("releases.json", "releases-2005-2007.json")) {
            try (Reader reader = resource(file)) { releases.addAll(Arrays.asList(GSON.fromJson(reader, Release[].class))); }
        }
        Release.setReleases(releases.toArray(new Release[0]));
        try (Reader reader = resource("items.json")) {
            EntityDefinition.itemDefinitions = GSON.fromJson(reader, new TypeToken<Map<Integer, EntityDefinition>>(){}.getType());
        }
        try (Reader reader = resource("item-release-overrides.json")) {
            EntityDefinition.itemReleaseOverrides = GSON.fromJson(reader, new TypeToken<Map<Integer, String>>(){}.getType());
        }
        try (Reader reader = resource("monsters.json")) {
            EntityDefinition.monsterDefinition = GSON.fromJson(reader, new TypeToken<Map<Integer, EntityDefinition>>(){}.getType());
        }
        try (BufferedReader reader = new BufferedReader(resource("quest-dates.tsv"))) {
            String line;
            while ((line = reader.readLine()) != null) {
                String[] fields = line.split("\t");
                expectedQuests.put(Quest.valueOf(fields[0]), LocalDate.parse(fields[1]));
            }
        }
    }
    @Test public void everySelectorResolvesToItsLabelDateAndCutoff() {
        for (ReleaseDate value : ReleaseDate.values()) {
            assertEquals(value.getLocalDate(), Release.getReleaseByDate(value).getDate().getLocalDate());
            assertTrue(HistoricalCutoff.isSupported(value.getLocalDate()));
        }
        assertEquals(LocalDate.of(2001,1,28), ReleaseDate.JANUARY_2001.getLocalDate());
        assertEquals(LocalDate.of(2001,9,30), ReleaseDate.SEPTEMBER_2001.getLocalDate());
        assertEquals(LocalDate.of(2003,9,30), ReleaseDate.SEPTEMBER_2003.getLocalDate());
    }
    @Test public void allHistoricalQuestsAndSubquestsHaveExactDatesAtEveryRelease() {
        assertEquals(146, expectedQuests.size());
        for (Release r : Release.getRELEASES()) {
            Set<Quest> expected = expectedQuests.entrySet().stream()
                .filter(e -> !e.getValue().isAfter(r.getDate().getLocalDate())).map(Map.Entry::getKey).collect(Collectors.toSet());
            List<Quest> actual = Release.getQuests(r);
            assertEquals(r.getDate().toString(), expected, new HashSet<>(actual));
            assertEquals(actual.size(), new HashSet<>(actual).size());
        }
    }
    @Test public void everyEntityDateIsInclusiveAndNeverLeaksPastBackup() {
        for (Map<Integer, EntityDefinition> map : Arrays.asList(EntityDefinition.itemDefinitions, EntityDefinition.monsterDefinition)) {
            for (EntityDefinition def : map.values()) {
                String value = def.getReleaseDate();
                if (value == null) { assertFalse(EntityDefinition.isUnlocked(def, date("2007-08-10"))); continue; }
                LocalDate introduced = LocalDate.parse(value);
                if (introduced.isAfter(HistoricalCutoff.OSRS_BACKUP)) {
                    assertFalse(EntityDefinition.isUnlocked(def, date("2099-01-01")));
                } else {
                    assertTrue(def.getName(), EntityDefinition.isUnlocked(def, date(value)));
                    assertFalse(def.getName(), EntityDefinition.isUnlocked(def, date(introduced.minusDays(1).toString())));
                }
            }
        }
    }
    @Test public void verifiedLegacyItemDateGapsAreRecoveredWithoutOpeningUnknownItems() throws Exception {
        assertEquals(3, EntityDefinition.itemReleaseOverrides.size());

        // Half plain pizza is a real consumable state from the 11 June 2001 pizza update.
        assertFalse(EntityDefinition.isItemUnlocked(2291, date("2001-06-10")));
        assertTrue(EntityDefinition.isItemUnlocked(2291, date("2001-06-11")));
        assertTrue(EntityDefinition.isItemUnlocked(2292, date("2001-06-11")));

        // ID 9947 was introduced in a hidden update between 6 and 13 November 2006.
        // Use the end of the documented window so it can never unlock early.
        assertFalse(EntityDefinition.isItemUnlocked(9947, date("2006-11-12")));
        assertTrue(EntityDefinition.isItemUnlocked(9947, date("2006-11-13")));

        // Null-date interface/modern placeholders remain fail-closed unless explicitly verified.
        assertFalse(EntityDefinition.isItemUnlocked(11117, date("2007-08-10")));
    }

    @Test public void missingAndMalformedEntityDatesAreLocked() throws Exception {
        assertFalse(EntityDefinition.isItemUnlocked(Integer.MAX_VALUE, date("2007-08-10")));
        assertFalse(EntityDefinition.isMonsterUnlocked(Integer.MAX_VALUE, date("2007-08-10")));
        for (String value : Arrays.asList("not-a-date", "2005-02-30", "", "2007-08-11")) {
            EntityDefinition def = GSON.fromJson("{\"releaseDate\":\"" + value + "\"}", EntityDefinition.class);
            assertFalse(EntityDefinition.isUnlocked(def, date("2007-08-10")));
        }
    }
    @Test public void skillsAndSailingStayWithinHistoricalBounds() {
        assertFalse(Release.getSkills(release("2001-01-04")).contains(Skill.CRAFTING));
        assertTrue(Release.getSkills(release("2001-05-08")).contains(Skill.CRAFTING));
        assertFalse(Release.getSkills(release("2005-01-17")).contains(Skill.SLAYER));
        assertTrue(Release.getSkills(release("2005-01-26")).contains(Skill.SLAYER));
        assertEquals(23, Release.getSkills(release("2007-08-10")).size());
        for (Release r : Release.getRELEASES()) assertFalse(Release.getSkills(r).contains(Skill.SAILING));
        assertTrue(HistoricalPermanentExclusions.isSailingWidget(InterfaceID.Stats.SAILING));
        assertTrue(HistoricalPermanentExclusions.isSailingWidget(InterfaceID.SAILING_SIDEPANEL << 16));
        assertTrue(HistoricalPermanentExclusions.isSailingMenuAction("Open", "<col=fff>Sailing</col>"));
        assertFalse(HistoricalPermanentExclusions.isSailingMenuAction("Travel", "Captain Barnaby"));
    }
    @Test public void prayerReleaseBoundariesAreCorrect() {
        assertFalse(Release.getPrayers(release("2005-08-30")).contains(Prayer.SMITE));
        assertTrue(Release.getPrayers(release("2005-09-06")).containsAll(Arrays.asList(Prayer.SMITE, Prayer.REDEMPTION, Prayer.RETRIBUTION)));
        assertFalse(Release.getPrayers(release("2006-08-15")).contains(Prayer.EAGLE_EYE));
        assertTrue(Release.getPrayers(release("2006-08-22")).contains(Prayer.EAGLE_EYE));
        assertFalse(Release.getPrayers(release("2007-07-17")).contains(Prayer.PIETY));
        assertTrue(Release.getPrayers(release("2007-07-24")).contains(Prayer.PIETY));
        assertFalse(Release.getPrayers(release("2007-08-10")).contains(Prayer.RIGOUR));
    }
    @Test public void allThreeSpellbooksUnlockAndModernSpellsStayLocked() {
        assertFalse(HistoricalSpellRestrictions.allowed("Ice Barrage", Release.getSpells(release("2005-04-11"))));
        assertTrue(HistoricalSpellRestrictions.allowed("<col=fff>Ice Barrage</col> -> Goblin", Release.getSpells(release("2005-04-18"))));
        assertFalse(HistoricalSpellRestrictions.allowed("Vengeance", Release.getSpells(release("2006-07-17"))));
        assertTrue(HistoricalSpellRestrictions.allowed("Vengeance", Release.getSpells(release("2006-07-24"))));
        assertFalse(HistoricalSpellRestrictions.allowed("Dream", Release.getSpells(release("2007-05-08"))));
        assertTrue(HistoricalSpellRestrictions.allowed("Dream", Release.getSpells(release("2007-05-15"))));
        List<RewindSpell> last = Release.getSpells(release("2007-08-10"));
        for (String name : Arrays.asList("Wind Surge", "Tan Leather", "Recharge Dragonstone", "Ourania Teleport", "Teleport to Boat", "Kourend Castle Teleport"))
            assertFalse(name, HistoricalSpellRestrictions.allowed(name, last));
        assertFalse(HistoricalSpellRestrictions.allowed("Vengeance Other", Collections.singletonList(RewindSpell.VENGEANCE)));
        assertTrue(HistoricalSpellRestrictions.allowedWidget(InterfaceID.MagicSpellbook.ICE_BARRAGE, last));
        assertFalse(HistoricalSpellRestrictions.allowedWidget(InterfaceID.MagicSpellbook.TELEPORT_ME_TO_BOAT, last));
    }
    @Test public void regionStateIsCumulativeAndUnknownUndergroundRegionsAreLocked() {
        Release last = release("2007-08-10");
        HistoricalRegionState.setSelectedDate(last.getDate().getDate());
        HistoricalRegionState.replaceWith(Release.getRegions(last));
        assertTrue(HistoricalRegionState.isRegionUnlocked(12850)); // Lumbridge
        assertTrue(HistoricalRegionState.isRegionUnlocked(15148)); // Harmony, not Feldip
        assertTrue(HistoricalRegionState.isRegionUnlocked(10835)); // Dorgesh-Kaan
        assertFalse(HistoricalRegionState.isRegionUnlocked( (20 << 8) | 75));
        assertFalse(HistoricalRegionState.isRegionUnlocked( (20 << 8) | 150));
        HistoricalRegionState.replaceWith(Release.getRegions(release("2005-01-31")));
        assertFalse(HistoricalRegionState.isRegionUnlocked(15148));
    }
    @Test public void sailingObjectsExcludeLegacyPassengerPlanks() {
        Integer[] ids = GSON.fromJson(resource("sailing-objects.json"), Integer[].class);
        Set<Integer> locked = new HashSet<>(Arrays.asList(ids));
        assertEquals(ids.length, locked.size());
        assertTrue(locked.contains(60552));
        assertFalse(locked.contains(17392));
    }
}

package com.rewind;

import com.rewind.regionlocker.HistoricalRegionState;
import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.BeforeClass;
import org.junit.Test;
import static org.junit.Assert.*;

public class HistoricalRegionAuditTest {
    private static class Area {
        String name;
        String date;
        List<Integer> regions;
    }

    @BeforeClass public static void load() throws Exception { HistoricalDataTest.load(); }

    @Test public void reviewedAreasUnlockTogetherAtTheirDocumentedBoundary() throws Exception {
        Area[] areas;
        try (InputStreamReader reader = new InputStreamReader(
            getClass().getResourceAsStream("region-boundaries.json"), StandardCharsets.UTF_8)) {
            areas = new Gson().fromJson(reader, Area[].class);
        }
        for (Release release : Release.getRELEASES()) {
            HistoricalRegionState.setSelectedDate(release.getDate().getDate());
            HistoricalRegionState.replaceWith(Release.getRegions(release));
            for (Area area : areas) {
                boolean expected = !release.getDate().getLocalDate().isBefore(LocalDate.parse(area.date));
                for (int region : area.regions) {
                    assertEquals(area.name + " / " + region + " at " + release.getDate(),
                        expected, HistoricalRegionState.isRegionUnlocked(region));
                }
            }
        }
    }

    @Test public void regionAssignmentsAreUniqueAndWithinThePackedIdRange() {
        Set<Integer> seen = new HashSet<>();
        for (Release release : Release.getRELEASES()) {
            for (int region : release.getRegions()) {
                assertTrue("Invalid region " + region, region >= 0 && region <= 65535);
                assertTrue("Duplicate region " + region, seen.add(region));
            }
        }
    }

    @Test public void fixingHistoricalMinigamesDoesNotOpenModernDedicatedAreas() {
        Release last = Release.getRELEASES().get(Release.getRELEASES().size() - 1);
        HistoricalRegionState.setSelectedDate(last.getDate().getDate());
        HistoricalRegionState.replaceWith(Release.getRegions(last));
        for (int region : new int[]{9043, 10063, 10064, 9807, 13151, 12895, 14642,
            13136, 12889, 12611, 14160, 9033, 11675, 12119}) {
            assertFalse("Post-backup/dedicated modern region " + region,
                HistoricalRegionState.isRegionUnlocked(region));
        }
    }
}

package com.rewind;

import net.runelite.client.config.ConfigGroup;
import net.runelite.client.plugins.PluginDescriptor;
import org.junit.Test;
import static org.junit.Assert.*;

public class RebrandCompatibilityTest
{
    @Test public void publicNameAndSavedKeysAreIndependent()
    {
        PluginDescriptor descriptor = RewindPlugin.class.getAnnotation(PluginDescriptor.class);
        assertEquals("Rewind", descriptor.name());
        assertEquals("Experience Old School RuneScape through its historical timeline.", descriptor.description());
        assertEquals("chronoplugin", descriptor.configName());
        assertEquals("chrono", RewindConfig.class.getAnnotation(ConfigGroup.class).value());
        assertEquals("releasedate", RewindPlugin.CONFIG_RELEASE_DATE_KEY);
    }

