	 */
	public void setFont(int fontID)
	{
		this.getWidget().setFontId(fontID);
	}

	/**
	 * Sets the colour of the label text
	 * @param colour the RGB colour
	 */
	public void setColour(int colour)
	{
		this.getWidget().setTextColor(colour);
	}
}

package com.rewind.ui;

import lombok.Getter;
import lombok.Setter;
import net.runelite.api.ScriptEvent;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;

import java.util.ArrayList;
import java.util.List;

/**
 * UI Component classes allow for complex user interface functionality by
 * wrapping the gaming widget and carefully controlling its behaviour
 * @author Antipixel
 */
public abstract class UIComponent
{
	private static final int MAX_OPACITY = 255;
	private static final String BTN_NAME_FORMAT = "<col=ff9040>%s</col>";

	@Getter
	private Widget widget;

	/* Actions and events */
	private List<MenuAction> actions;

	@Setter
	private ComponentEventListener hoverListener;

	@Setter
	private ComponentEventListener leaveListener;

	/**
	 * Constructs a new UIComponent
	 * @param widget the underlying game widget
	 */
	public UIComponent(Widget widget)
	{
		this.widget = widget;

		// Assign the event listeners to the widget
		this.widget.setOnOpListener((JavaScriptCallback) this::onActionSelected);
		this.widget.setOnMouseOverListener((JavaScriptCallback) this::onMouseHover);
		this.widget.setOnMouseLeaveListener((JavaScriptCallback) this::onMouseLeave);
		this.widget.setHasListener(true);

		this.actions = new ArrayList<>();
	}

	/**
	 * Adds an action option to the component's menu
	 * @param action the action name
 	 * @param callback the callback event, which is trigger upon the
	 *                 selection of this menu option
	 */
	public void addAction(String action, MenuAction callback)
	{
		this.widget.setAction(actions.size(), action);
		this.actions.add(callback);
	}

	/**
	 * Triggered upon the selection of menu option
	 * @param e the script event
	 */
	protected void onActionSelected(ScriptEvent e)
	{
		// If there's no actions specified, ignore
		if (this.actions.isEmpty())
			return;

		// Get the action action event object for this menu option
		MenuAction actionEvent = this.actions.get(e.getOp() - 1);

		// Call the action listener for this option
		actionEvent.onMenuAction();
	}

	/**
	 * Triggered upon the mouse entering the component
	 * @param e the script event
	 */
	protected void onMouseHover(ScriptEvent e)
	{
		// If a hover event is specified, trigger it
		if (this.hoverListener != null)
			this.hoverListener.onComponentEvent(this);
	}

	/**
	 * Triggered upon the mouse leaving the component
	 * @param e the script event
	 */
	protected void onMouseLeave(ScriptEvent e)
	{
		// If a leave event is specified, trigger it
		if (this.leaveListener != null)
			this.leaveListener.onComponentEvent(this);
	}

	/**
	 * Sets a listener which will be called upon the mouse
	 * hovering over the widget
	 * @param listener the listener
	 */
	public void setOnHoverListener(ComponentEventListener listener)
	{
		this.hoverListener = listener;
	}

	/**
	 * Sets a listener which will be called upon the mouse
	 * exiting from over the widget
	 * @param listener the listener
	 */
	public void setOnLeaveListener(ComponentEventListener listener)
	{
		this.leaveListener = listener;
	}

	/**
	 * Sets the name of the component widget
	 * @param name the component name
	 */
	public void setName(String name)
	{
		this.widget.setName(String.format(BTN_NAME_FORMAT, name));
	}

	/**
	 * Sets the component size
	 * @param width the component width
	 * @param height the component height
	 */
	public void setSize(int width, int height)
	{
		this.widget.setOriginalWidth(width);
		this.widget.setOriginalHeight(height);
	}

	/**
	 * Sets the position of the component, relative
	 * to the parent layer widget
	 * @param x the x position
	 * @param y the y position
	 */
	public void setPosition(int x, int y)
	{
		this.setX(x);
		this.setY(y);
	}

	/**
	 * Sets the X position of the component, relative
	 * to the parent layer
	 * @param x the x position
	 */
	public void setX(int x)
	{
		this.widget.setOriginalX(x);
	}

	/**
	 * Sets the Y position of the component, relative
	 * to the parent layer
	 * @param y the x position
	 */
	public void setY(int y)
	{
		this.widget.setOriginalY(y);
	}

	/**
	 * Gets the X position of the component, relative
	 * to the the parent layer
	 * @return the x position
	 */
	public int getX()
	{
		return this.widget.getOriginalX();
	}

	/**
	 * Gets the Y position of the component, relative
	 * to the the parent layer
	 * @return the y position
	 */
	public int getY()
	{
		return this.widget.getOriginalY();
	}


	/**
	 * Sets the visibility of the component
	 * @param visible true for visible, false for hidden
	 */
	public void setVisibility(boolean visible)
	{
		this.widget.setHidden(!visible);
	}

	/**
	 * Sets the opacity of the widget
	 * @param opacity the opacity value. Expects a value
	 *                between 0.0 (transparent) and 1.0 (opaque)
	 */
	public void setOpacity(float opacity)
	{
		// Cap the opacity to 1.0
		if (opacity > 1.0)
			opacity = 1.0f;

		// Invert the percentage
		float percentage = 1.0f - opacity;

		// Convert the percentage value to a 0-255 integer
		this.widget.setOpacity((int)(percentage * MAX_OPACITY));
	}

	/**
	 * Gets the opacity of the widget
	 * @return an opacity value between 0.0 (transparent) and 1.0 (opaque)
	 */
	public float getOpacity()
	{
		// Convert the opacity to a percentage
		float opacity = (float)this.widget.getOpacity() / MAX_OPACITY;

		// Invert the percentage
		return 1.0f - opacity;
	}

	public void clearActions() {
		actions.clear();
	}
}

package com.rewind;

import net.runelite.api.Skill;

public final class HistoricalPermanentExclusions
{
    private HistoricalPermanentExclusions() {}

    public static boolean isSkillPermanentlyLocked(Skill skill)
    {
        return skill == Skill.SAILING;
    }

    public static boolean isSailingWidget(int packedId)
    {
        int group = packedId >>> 16;
        return packedId == net.runelite.api.gameval.InterfaceID.Stats.SAILING
            || group == net.runelite.api.gameval.InterfaceID.SAILING_MENU
            || group == net.runelite.api.gameval.InterfaceID.SAILING_INTRO_HUD
            || (group >= net.runelite.api.gameval.InterfaceID.SAILING_BT_HUD
                && group <= net.runelite.api.gameval.InterfaceID.SAILING_CUSTOMISATION)
            || group == net.runelite.api.gameval.InterfaceID.SAILING_BOAT_CARGOHOLD
            || group == net.runelite.api.gameval.InterfaceID.SAILING_BOAT_CARGOHOLD_SIDE;
    }

    public static boolean isSailingMenuAction(String option, String target)
    {
        String o = option == null ? "" : option.toLowerCase(java.util.Locale.ROOT);
        String t = target == null ? "" : target.replaceAll("<[^>]*>", "").toLowerCase(java.util.Locale.ROOT);
        return o.contains("sailing") || t.contains("sailing") || t.contains("sailing boat");
    }
}

package com.rewind;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Prayer;
import net.runelite.api.Quest;
import net.runelite.api.Skill;

import java.util.*;

@Slf4j
public class Release {
    @Getter
    private static List<Release> RELEASES = new ArrayList<>();

    @Getter
    private ReleaseDate date;
    @Getter
    private List<Integer> regions;
    @Getter
    private List<Skill> skills;
    @Getter
    private List<Prayer> prayers;
    @Getter
    private List<Quest> quests;
    @Getter
    private List<RewindSpell> spells;
    @Getter
    private String description;

    public Release(ReleaseDate date, List<Integer> regions, List<Skill> skills, List<Prayer> prayers, List<Quest> quests, List<RewindSpell> spells, String description) {
        this.date = date;
        this.skills = skills;
        this.regions = regions;
        this.prayers = prayers;
        this.quests = quests;
        this.spells = spells;
        this.description = description;
    }

    public static void setReleases(Release[] releases) {
        RELEASES = Arrays.stream(releases)
            .sorted(Comparator.comparing(r -> r.date.getLocalDate()))
            .collect(java.util.stream.Collectors.toList());
        for (Release r : RELEASES) {
            if (r.date == null || !HistoricalCutoff.isSupported(r.date.getLocalDate()))
                throw new IllegalArgumentException("Unsupported historical release");
            for (List<?> values : Arrays.asList(r.skills, r.prayers, r.quests, r.spells))
                if (values != null && values.contains(null))
                    throw new IllegalArgumentException("Unknown enum in release " + r.date);
        }
    }

    public static Release getReleaseByDate(ReleaseDate date) {
        return RELEASES.stream().filter(r -> r.date.getLocalDate().equals(date.getLocalDate()))
            .findFirst().orElseThrow(() -> new IllegalArgumentException("Missing release: " + date));
    }

    public static List<Integer> getRegions(Release release) {
        LinkedHashSet<Integer> regions = new LinkedHashSet<>();

        for (Release r : RELEASES) {
            if (r.date.getLocalDate().isAfter(release.date.getLocalDate())) break;
            if (r.regions != null) regions.addAll(r.getRegions());

        }

        return new ArrayList<>(regions);
    }

    public static List<Skill> getSkills(Release release) {
        List<Skill> skills = new ArrayList<>();

        for(Release r : RELEASES) {
            if (r.date.getLocalDate().isAfter(release.date.getLocalDate())) break;
            if(r.skills != null) skills.addAll(r.getSkills());

        }

        skills.removeIf(HistoricalPermanentExclusions::isSkillPermanentlyLocked);
        return skills;
    }

    public static List<Prayer> getPrayers(Release release) {
        List<Prayer> prayers = new ArrayList<>();

        for(Release r : RELEASES) {
            if (r.date.getLocalDate().isAfter(release.date.getLocalDate())) break;
            if(r.prayers != null) prayers.addAll(r.getPrayers());

        }

        return prayers;
    }

    public static List<Quest> getQuests(Release release) {
        List<Quest> quests = new ArrayList<>();

        for(Release r : RELEASES) {
            if (r.date.getLocalDate().isAfter(release.date.getLocalDate())) break;
            if(r.quests != null) quests.addAll(r.getQuests());

        }

        return quests;
    }

    public static List<RewindSpell> getSpells(Release release) {
        List<RewindSpell> spells = new ArrayList<>();

        for(Release r : RELEASES) {
            if (r.date.getLocalDate().isAfter(release.date.getLocalDate())) break;
            if(r.spells != null) spells.addAll(r.getSpells());

        }

        return spells;
    }
}

package com.rewind;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;

/** Player-facing summary of the currently selected historical release. */
public class RewindPanel extends PluginPanel
{
    private final RewindPlugin plugin;
    private final JLabel dateValue = valueLabel();
    private final JLabel description = new JLabel();
    private final JLabel regionsValue = valueLabel();
    private final JLabel questsValue = valueLabel();
    private final JLabel skillsValue = valueLabel();
    private final JLabel prayersValue = valueLabel();
    private final JLabel spellsValue = valueLabel();
    private final JLabel geValue = valueLabel();
    private final JButton geToggle = new JButton();
    private final JLabel homeTeleportValue = valueLabel();
    private final JButton homeTeleportToggle = new JButton();
    private final JPanel timelineSelector = card();
    private final JComboBox<ReleaseDate> timelineDates = new JComboBox<>();

    public RewindPanel(RewindPlugin plugin)
    {
        this.plugin = plugin;
        setLayout(new BorderLayout());
        setBorder(new EmptyBorder(10, 10, 10, 10));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel content = new JPanel();
        content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
        content.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JLabel title = new JLabel("Rewind");
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(Color.WHITE);
        title.setAlignmentX(Component.LEFT_ALIGNMENT);
        content.add(title);

        JLabel subtitle = new JLabel("<html>Experience Old School RuneScape<br>through its historical timeline.</html>");
        subtitle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        subtitle.setBorder(new EmptyBorder(3, 0, 12, 0));
        subtitle.setAlignmentX(Component.LEFT_ALIGNMENT);
        content.add(subtitle);

        content.add(sectionTitle("CURRENT DATE"));
        JPanel dateCard = card();
        dateValue.setFont(FontManager.getRunescapeBoldFont());
        dateValue.setForeground(Color.WHITE);
        dateValue.setAlignmentX(Component.LEFT_ALIGNMENT);
        dateCard.add(dateValue);
        description.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        description.setBorder(new EmptyBorder(6, 0, 0, 0));
        description.setAlignmentX(Component.LEFT_ALIGNMENT);
        dateCard.add(description);

        JButton changeTimeline = new JButton("Change Timeline");
        changeTimeline.setFocusable(false);
        changeTimeline.setAlignmentX(Component.LEFT_ALIGNMENT);
        changeTimeline.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
        changeTimeline.setToolTipText("Choose a historical date");
        changeTimeline.addActionListener(e -> toggleTimelineSelector());
        dateCard.add(Box.createVerticalStrut(8));
        dateCard.add(changeTimeline);
        content.add(dateCard);

        buildTimelineSelector();
        timelineSelector.setVisible(false);
        content.add(Box.createVerticalStrut(6));
        content.add(timelineSelector);
        content.add(Box.createVerticalStrut(10));

        content.add(sectionTitle("TIMELINE PROGRESS"));
        JPanel unlockCard = card();
        unlockCard.add(row("Regions", regionsValue));
        unlockCard.add(row("Quests", questsValue));
        unlockCard.add(row("Skills", skillsValue));
        unlockCard.add(row("Prayers", prayersValue));
        unlockCard.add(row("Spells", spellsValue));
        content.add(unlockCard);
        content.add(Box.createVerticalStrut(10));

        content.add(sectionTitle("ACCESS"));
        JPanel accessCard = card();
        accessCard.add(row("Grand Exchange", geValue));
        geToggle.setFocusable(false);
        geToggle.setAlignmentX(Component.LEFT_ALIGNMENT);
        geToggle.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
        geToggle.setToolTipText("Toggle the Grand Exchange historical access override");
        geToggle.addActionListener(e -> toggleGrandExchange());
        accessCard.add(Box.createVerticalStrut(8));
        accessCard.add(geToggle);
        accessCard.add(Box.createVerticalStrut(10));
        accessCard.add(row("Home Teleport", homeTeleportValue));
        homeTeleportToggle.setFocusable(false);
        homeTeleportToggle.setAlignmentX(Component.LEFT_ALIGNMENT);
        homeTeleportToggle.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
        homeTeleportToggle.setToolTipText("Toggle the Home Teleport historical access override");
        homeTeleportToggle.addActionListener(e -> toggleHomeTeleport());
        accessCard.add(Box.createVerticalStrut(8));
        accessCard.add(homeTeleportToggle);
        content.add(accessCard);

        add(content, BorderLayout.NORTH);
        refresh();
    }

    public void refresh()
    {
        Release release = plugin.getCurrentRelease();
        if (release == null)
        {
            return;
        }

        dateValue.setText(release.getDate().getName());
        description.setText(html(release.getDescription()));
        Release finalRelease = Release.getReleaseByDate(ReleaseDate._10_AUGUST_2007);
        regionsValue.setText(progress(Release.getRegions(release).size(), Release.getRegions(finalRelease).size()));
        questsValue.setText(progress(Release.getQuests(release).size(), Release.getQuests(finalRelease).size()));
        skillsValue.setText(progress(Release.getSkills(release).size(), Release.getSkills(finalRelease).size()));
        prayersValue.setText(progress(Release.getPrayers(release).size(), Release.getPrayers(finalRelease).size()));
        spellsValue.setText(progress(Release.getSpells(release).size(), Release.getSpells(finalRelease).size()));
        boolean geUnlocked = plugin.getConfig().unlockGrandExchange();
        geValue.setText(geUnlocked ? "Enabled" : "Locked");
        geToggle.setText(geUnlocked ? "Disable Access" : "Enable Access");
        boolean homeTeleportUnlocked = plugin.getConfig().unlockHomeTeleport();
        homeTeleportValue.setText(homeTeleportUnlocked ? "Enabled" : "Locked");
        homeTeleportToggle.setText(homeTeleportUnlocked ? "Disable Access" : "Enable Access");
    }

    private void toggleGrandExchange()
    {
        boolean enable = !plugin.getConfig().unlockGrandExchange();
        plugin.getConfigManager().setConfiguration(
            RewindPlugin.CONFIG_GROUP_KEY,
            "unlockGrandExchange",
            enable);
    }

    private void toggleHomeTeleport()
    {
        boolean enable = !plugin.getConfig().unlockHomeTeleport();
        plugin.getConfigManager().setConfiguration(
            RewindPlugin.CONFIG_GROUP_KEY,
            "unlockHomeTeleport",
            enable);
    }

    private void buildTimelineSelector()
    {
        JLabel label = new JLabel("Choose a historical date");
        label.setForeground(Color.WHITE);
        label.setAlignmentX(Component.LEFT_ALIGNMENT);
        timelineSelector.add(label);
        timelineSelector.add(Box.createVerticalStrut(6));

        DefaultComboBoxModel<ReleaseDate> model = new DefaultComboBoxModel<>();
        for (ReleaseDate date : ReleaseDate.values())
        {
            if (HistoricalCutoff.isSupported(date.getLocalDate()))
            {
                model.addElement(date);
            }
        }
        timelineDates.setModel(model);
        timelineDates.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
        timelineDates.setAlignmentX(Component.LEFT_ALIGNMENT);
        timelineSelector.add(timelineDates);
        timelineSelector.add(Box.createVerticalStrut(8));

        JPanel actions = new JPanel(new GridLayout(1, 2, 6, 0));
        actions.setOpaque(false);
        actions.setAlignmentX(Component.LEFT_ALIGNMENT);
        actions.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));

        JButton cancel = new JButton("Cancel");
        cancel.setFocusable(false);
        cancel.addActionListener(e -> timelineSelector.setVisible(false));
        actions.add(cancel);

        JButton apply = new JButton("Apply");
        apply.setFocusable(false);
        apply.addActionListener(e -> applyTimelineSelection());
        actions.add(apply);
        timelineSelector.add(actions);
    }

    private void toggleTimelineSelector()
    {
        boolean show = !timelineSelector.isVisible();
        if (show)
        {
            timelineDates.setSelectedItem(plugin.getConfig().release());
        }
        timelineSelector.setVisible(show);
        revalidate();
        repaint();
    }

    private void applyTimelineSelection()
    {
        ReleaseDate current = plugin.getConfig().release();
        ReleaseDate selected = (ReleaseDate) timelineDates.getSelectedItem();
        if (selected != null && selected != current)
        {
            plugin.getConfigManager().setConfiguration(
                RewindPlugin.CONFIG_GROUP_KEY,
                RewindPlugin.CONFIG_RELEASE_DATE_KEY,
                selected);
        }
        timelineSelector.setVisible(false);
        revalidate();
        repaint();
    }

    /** Kept for the existing config-change call site. */
    public void updateDescription(String ignored)
    {
        refresh();
    }

    private static JLabel sectionTitle(String text)
    {
        JLabel label = new JLabel(text);
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setForeground(ColorScheme.BRAND_ORANGE);
        label.setBorder(new EmptyBorder(0, 0, 4, 0));
        label.setAlignmentX(Component.LEFT_ALIGNMENT);
        return label;
    }

    private static JPanel card()
    {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        panel.setBorder(new EmptyBorder(8, 8, 8, 8));
        panel.setAlignmentX(Component.LEFT_ALIGNMENT);
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 180));
        return panel;
    }

    private static JPanel row(String name, JLabel value)
    {
        JPanel row = new JPanel(new BorderLayout());
        row.setOpaque(false);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));
        JLabel key = new JLabel(name);
        key.setForeground(Color.WHITE);
        row.add(key, BorderLayout.WEST);
        row.add(value, BorderLayout.EAST);
        return row;
    }

    private static JLabel valueLabel()
    {
        JLabel label = new JLabel();
        label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        return label;
    }

    private static String progress(int current, int total)
    {
        return current + " / " + total;
    }

    private static String html(String text)
    {
        if (text == null || text.trim().isEmpty())
        {
            return "<html><i>No release notes for this date.</i></html>";
        }
        return "<html>" + text + "</html>";
    }
}

