    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked e) throws ParseException {
        String option = HistoricalSpellRestrictions.clean(e.getMenuOption());
        String target = HistoricalSpellRestrictions.clean(e.getMenuTarget());
        Widget widget = e.getWidget();
        int group = widget == null ? -1 : widget.getId() >>> 16;
        if (HistoricalPermanentExclusions.isSailingMenuAction(option, target)
            || (widget != null && HistoricalPermanentExclusions.isSailingWidget(widget.getId()))) {
            deny(e); return;
        }
        // The scene mask is visual only. Enforce the same region boundary on direct
        // movement/object/ground-item actions so blacked-out regions are not still usable.
        if (isSceneLocationAction(e.getMenuAction())) {
            WorldPoint actionLocation = getMenuWorldPoint(e);
            if (actionLocation != null && !HistoricalRegionState.isTileUnlocked(actionLocation)) {
                deny(e); return;
            }
        }
        // Greyed pre-release skills should not still open their modern skill guides.
        if (widget != null && option.toLowerCase(Locale.ROOT).startsWith("view ")) {
            Skill skill = RewindSkillOverlay.skillForWidget(widget);
            if (skill != null && (HistoricalPermanentExclusions.isSkillPermanentlyLocked(skill)
                || !Release.getSkills(currentRelease).contains(skill))) {
                deny(e); return;
            }
        }
        // Quick prayers are a post-2007 feature and can activate locked prayers in one click.
        if ((option.toLowerCase(java.util.Locale.ROOT).contains("quick-prayer")
            || target.toLowerCase(java.util.Locale.ROOT).contains("quick-prayer"))
            && !option.toLowerCase(java.util.Locale.ROOT).contains("deactivate")) {
            deny(e); return;
        }
        if (option.equals("Activate") && (group == InterfaceID.PRAYERBOOK
            || Arrays.stream(RewindPrayer.values()).anyMatch(p -> p.getName().equalsIgnoreCase(target)))) {
            boolean allowed = Arrays.stream(RewindPrayer.values()).anyMatch(p ->
                p.getName().equalsIgnoreCase(target) && Release.getPrayers(currentRelease).contains(p.getPrayer()));
            if (!allowed) { deny(e); return; }
        }
        if (group == InterfaceID.PRAYERBOOK && isPrayerActivation(option)
            && !isPrayerWidgetUnlocked(widget, target)) {
            deny(e); return;
        }
        List<RewindSpell> spells = Release.getSpells(currentRelease);
        if (option.equals("Cast") || option.toLowerCase(java.util.Locale.ROOT).contains("autocast")) {
            if (!HistoricalSpellRestrictions.allowed(target, spells)) { deny(e); return; }
        }
        if (group == InterfaceID.MAGIC_SPELLBOOK && e.getMenuAction() == net.runelite.api.MenuAction.WIDGET_TARGET
            && !HistoricalSpellRestrictions.allowedWidget(widget.getId(), spells)) {
            deny(e); return;
        }
        // Re-check a previously selected spell/item after changing the historical date.
        if (e.getMenuAction().name().startsWith("WIDGET_TARGET_ON_")) {
            Widget selected = client.getSelectedWidget();
            if (selected != null && selected.getId() >>> 16 == InterfaceID.MAGIC_SPELLBOOK
                && !HistoricalSpellRestrictions.allowedWidget(selected.getId(), spells)) {
                deny(e); return;
            }
            if (selected != null && selected.getItemId() >= 0 && !isItemUnlocked(selected.getItemId())) {
                deny(e); return;
            }
        }
        if ((e.getMenuAction().name().startsWith("GAME_OBJECT_")
            || e.getMenuAction() == net.runelite.api.MenuAction.WIDGET_TARGET_ON_GAME_OBJECT)
            && sailingObjects.contains(e.getId())) {
            deny(e); return;
        }
        NPC npc = e.getMenuEntry().getNpc();
        if (npc != null && !option.equals("Examine")
            && !isNpcUnlocked(npc)) {
            deny(e); return;
        }
        // Match actual item operations plus the known item-use verbs. Shop stock gets an
        // explicit group check because RuneScape may expose Buy actions as generic widget ops.
        // Do not gate every widget with an item id: several historical interfaces reuse
        // pseudo-item ids purely as icons (for example Construction/build menus).
        boolean itemAction = e.isItemOp() || MENU_BLACKLIST.contains(option)
            || e.getMenuAction().name().startsWith("GROUND_ITEM_")
            || e.getMenuAction() == net.runelite.api.MenuAction.WIDGET_TARGET
            || group == InterfaceID.SHOPMAIN;
        boolean disposal = option.equals("Drop") || option.equals("Destroy") || option.equals("Examine")
            || option.startsWith("Deposit") || option.equals("Release") || option.equals("Remove");
        int itemId = e.getItemId();
        if (e.getMenuAction().name().startsWith("GROUND_ITEM_")) itemId = e.getId();
        if ((widget != null && widget.getId() == InterfaceID.GeOffers.SETUP_CONFIRM)
            || (group == InterfaceID.GE_OFFERS && option.equalsIgnoreCase("Confirm"))) {
            itemId = client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);
        }
        if (config.unlockGrandExchange() && isGrandExchangeGroup(group)
            && itemId >= 0 && !isItemUnlocked(itemId)) {
            deny(e);
            addWarningMessage("This item was not available by " + config.release().getName() + ".", false);
            return;
        }
        if (itemAction && !disposal && itemId >= 0 && !isItemUnlocked(itemId)) {
            deny(e);
            addWarningMessage("This item is unavailable or has no verified release date for "
                + config.release().getName() + ".", false);
        }
    }

    private void deny(MenuOptionClicked event) {
        event.consume();
        client.playSoundEffect(SOUND_EFFECT_INACTIVE);
    }

    private void reloadScene() {
        clientThread.invokeLater(() -> {
            if (client.getGameState() == GameState.LOGGED_IN) client.setGameState(GameState.LOADING);
        });
    }

    private void refreshWidgets() {
        if (client.getGameState() != GameState.LOGGED_IN) return;
        updatePrayers();
        updateSpells();
        redrawQuests();
    }

    /**
     * RuneLite's quest-list script calls this callback once for each quest row while it
     * builds the native list. Force historically unavailable quests to be filtered out,
     * but leave already-filtered rows alone so RuneLite's own search/status filters and
     * native Free/Members/release-date grouping continue to work normally.
     */
    @Subscribe(priority = -1) // run after RuneLite's Quest List plugin
    public void onScriptCallbackEvent(ScriptCallbackEvent event) {
        if (!"questFilter".equals(event.getEventName()) || currentRelease == null) return;

        int[] intStack = client.getIntStack();
        int intStackSize = client.getIntStackSize();
        if (intStack == null || intStackSize < 2) return;

        int row = intStack[intStackSize - 1];
        Object[] displayName = client.getDBTableField(row, DBTableID.Quest.COL_DISPLAYNAME, 0);
        if (displayName == null || displayName.length == 0 || !(displayName[0] instanceof String)) return;

        if (!unlockedQuestNames.contains((String) displayName[0])) {
            intStack[intStackSize - 2] = 1;
        }
    }

    private void updateUnlockedQuestNames() {
        if (currentRelease == null) {
            unlockedQuestNames = Collections.emptySet();
            return;
        }
        Set<String> names = new HashSet<>();
        for (Quest quest : Release.getQuests(currentRelease)) {
            names.add(quest.getName());
        }
        unlockedQuestNames = names;
    }

    private void redrawQuests() {
        if (client.getGameState() != GameState.LOGGED_IN) return;
        Widget container = client.getWidget(InterfaceID.Questlist.CONTAINER);
        if (container == null) return;
        Object[] onVarTransmitListener = container.getOnVarTransmitListener();
        if (onVarTransmitListener == null) return;
        clientThread.invokeLater(() -> client.runScript(onVarTransmitListener));
    }

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded e) {
		if (e.getGroupId() == InterfaceID.TOPLEVEL_OSRS_STRETCH || e.getGroupId() == InterfaceID.TOPLEVEL) {
            this.updatePrayers();
		}
		else if(e.getGroupId() == InterfaceID.MAGIC_SPELLBOOK) {
			this.updateSpells();
		}
	}





	@VisibleForTesting
	boolean shouldDraw(Renderable renderable, boolean drawingUI) {
		if (renderable instanceof NPC)
		{
			NPC npc = (NPC) renderable;

			if(npc.getInteracting() == client.getLocalPlayer()) {
				return true;
			}

			try {
				return isNpcUnlocked(npc);
            } catch(ParseException e) {
                return false;
			}
		}

		return true;
	}

	private void addWarningMessage(String message, boolean playSound) {
		final ChatMessageBuilder chatMessage = new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT)
				.append(message)
				.append(ChatColorType.NORMAL);

		chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(chatMessage.build())
				.build());

        if (playSound) client.playSoundEffect(SOUND_EFFECT_FAIL);
	}

	public boolean isItemUnlocked(int itemId) throws ParseException {
        ItemComposition item = client.getItemDefinition(itemId);
        // A bank note is the same historical item, not an independent modern item.
        if (item.getNote() != -1) itemId = item.getLinkedNoteId();
        return EntityDefinition.isItemUnlocked(itemId, config.release().getDate());
	}

    private void updatePrayers() {
        List<Prayer> unlocked = Release.getPrayers(currentRelease);
        for (RewindPrayer prayer : RewindPrayer.values()) {
            Widget parent = client.getWidget(prayer.getPackedID());
            if (parent != null) parent.setOpacity(unlocked.contains(prayer.getPrayer()) ? 0 : 160);
        }
    }

    List<RewindSpell> getUnlockedSpells() {
        List<RewindSpell> unlocked = new ArrayList<>(Release.getSpells(currentRelease));
        if (config.unlockHomeTeleport()) {
            addVisibleHomeTeleport(unlocked, RewindSpell.LUMBRIDGE_HOME_TELEPORT);
            addVisibleHomeTeleport(unlocked, RewindSpell.EDGEVILLE_HOME_TELEPORT);
            addVisibleHomeTeleport(unlocked, RewindSpell.LUNAR_HOME_TELEPORT);
        }
        return unlocked;
    }

    private void addVisibleHomeTeleport(List<RewindSpell> spells, RewindSpell homeTeleport) {
        Widget widget = client.getWidget(homeTeleport.getPackedID());
        if (widget != null && !widget.isHidden() && !spells.contains(homeTeleport)) {
            spells.add(homeTeleport);
        }
    }

    private void updateSpells() {
        List<RewindSpell> unlocked = getUnlockedSpells();
        for (RewindSpell spell : RewindSpell.values()) {
            Widget widget = client.getWidget(spell.getPackedID());
            if (widget != null) widget.setOpacity(unlocked.contains(spell) ? 0 : 160);
        }
    }

    private void updateAdditionalRegions() {
        HistoricalRegionState.setAdditionallyUnlocked(config.unlockGrandExchange()
            ? Collections.singleton(GRAND_EXCHANGE_REGION) : Collections.emptySet());
    }

    private boolean isNpcUnlocked(NPC npc) throws ParseException {
        WorldPoint location = npc.getWorldLocation();
        WorldView worldView = npc.getWorldView();
        LocalPoint localPoint = npc.getLocalLocation();
        if (worldView != null && localPoint != null) {
            location = WorldPoint.fromLocalInstance(worldView.getScene(), localPoint, worldView.getPlane());
        }
        if (config.unlockGrandExchange() && location.getRegionID() == GRAND_EXCHANGE_REGION) {
            return true;
        }
        if (!HistoricalRegionState.isTileUnlocked(location)) {
            return false;
        }
        return EntityDefinition.isMonsterUnlocked(npc.getId(), npc.getName(), config.release().getDate());
    }

    @VisibleForTesting
    static boolean isSceneLocationAction(net.runelite.api.MenuAction action) {
        if (action == null) return false;
        String name = action.name();
        return name.equals("WALK")
            || name.contains("GAME_OBJECT")
            || name.contains("GROUND_ITEM");
    }

    private WorldPoint getMenuWorldPoint(MenuOptionClicked event) {
        Player player = client.getLocalPlayer();
        if (player == null) return null;
        WorldView worldView = player.getWorldView();

        // WALK menu parameters are not a reliable way to identify the clicked tile
        // across every RuneLite input path. RuneLite itself exposes the selected scene
        // tile for ordinary scene walking, so prefer that exact tile.
        if (event.getMenuAction() == net.runelite.api.MenuAction.WALK) {
            Tile selectedTile = client.getSelectedSceneTile();
            if (selectedTile != null) {
                return WorldPoint.fromLocalInstance(
                    worldView.getScene(), selectedTile.getLocalLocation(), selectedTile.getPlane());
            }
        }

        LocalPoint localPoint = LocalPoint.fromScene(event.getParam0(), event.getParam1(), worldView);
        if (localPoint == null) return null;
        return WorldPoint.fromLocalInstance(worldView.getScene(), localPoint, worldView.getPlane());
    }

    @VisibleForTesting
    static boolean isGrandExchangeGroup(int group) {
        return group == InterfaceID.GE_OFFERS || group == InterfaceID.GE_OFFERS_SIDE
            || group == InterfaceID.GE_PRICELIST;
    }

    @VisibleForTesting
    static boolean isPrayerActivation(String option) {
        String value = option == null ? "" : option.toLowerCase(Locale.ROOT);
        return value.contains("activate") && !value.contains("deactivate");
    }

    private boolean isPrayerWidgetUnlocked(Widget widget, String target) {
        List<Prayer> unlocked = Release.getPrayers(currentRelease);
        int widgetId = widget == null ? -1 : widget.getId();
        for (RewindPrayer prayer : RewindPrayer.values()) {
            if (prayer.getPackedID() == widgetId || prayer.getName().equalsIgnoreCase(target)) {
                return unlocked.contains(prayer.getPrayer());
            }
        }
        // Any prayer absent from the historical catalogue is post-backup content.
        return false;
    }

	public static int getCenterX(Widget window, int width) {
		return (window.getWidth() / 2) - (width / 2);
	}

	public static int getCenterY(Widget window, int height) {
		return (window.getHeight() / 2) - (height / 2);
	}
}

package com.rewind;

import lombok.Getter;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.format.DateTimeParseException;
import java.util.Collections;
import java.util.Date;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

@Getter
public class EntityDefinition {
    private static final int FIRST_LEGACY_PICKPOCKET_POUCH = 22521;
    private static final int LAST_LEGACY_PICKPOCKET_POUCH = 22538;
    private static final LocalDate THIEVING_RELEASE = LocalDate.of(2002, 4, 30);
    private int id;
    private String name;
    private String releaseDate;
    private String lastUpdated;
    static Map<Integer, EntityDefinition> itemDefinitions;
    static Map<Integer, EntityDefinition> monsterDefinition;
    static Map<Integer, String> itemReleaseOverrides = Collections.emptyMap();
    private static Map<String, LocalDate> earliestMonsterReleaseByName = Collections.emptyMap();

    static void indexMonsterDefinitions() {
        Map<String, LocalDate> indexed = new HashMap<>();
        if (monsterDefinition != null) {
            for (EntityDefinition def : monsterDefinition.values()) {
                if (def == null || def.name == null || def.releaseDate == null) continue;
                try {
                    LocalDate release = LocalDate.parse(def.releaseDate);
                    // Keep the earliest known release even when it is post-backup. This lets
                    // an otherwise unknown/new NPC id inherit a verified modern name date
                    // and remain locked instead of falling through as an ordinary NPC.
                    indexed.merge(normalizeName(def.name), release,
                        (first, second) -> first.isBefore(second) ? first : second);
                } catch (DateTimeParseException ignored) {
                    // Invalid source dates remain locked.
                }
            }
        }
        earliestMonsterReleaseByName = indexed;
    }

    private static String normalizeName(String name) {
        return name.trim().toLowerCase(Locale.ROOT);
    }

    // Unknown IDs and missing/invalid dates remain locked. IDs are never used as a date proxy.
    static boolean isUnlocked(EntityDefinition def, Date selected) {
        return isUnlockedDate(def == null ? null : def.releaseDate, selected);
    }

    private static boolean isUnlockedDate(String releaseDate, Date selected) {
        if (releaseDate == null || selected == null) return false;
        try {
            LocalDate introduced = LocalDate.parse(releaseDate);
            LocalDate date = selected.toInstant().atZone(ZoneId.systemDefault()).toLocalDate();
            return HistoricalCutoff.isSupported(introduced) && !introduced.isAfter(date);
        } catch (DateTimeParseException ex) {
            return false;
        }
    }

    public static boolean isItemUnlocked(int id, Date selected) throws java.text.ParseException {
        if (id >= FIRST_LEGACY_PICKPOCKET_POUCH && id <= LAST_LEGACY_PICKPOCKET_POUCH) {
            LocalDate date = selected.toInstant().atZone(ZoneId.systemDefault()).toLocalDate();
            return !date.isBefore(THIEVING_RELEASE);
        }
        EntityDefinition def = itemDefinitions == null ? null : itemDefinitions.get(id);
        if (def == null) return false;

        String release = def.releaseDate;
        if (release == null && itemReleaseOverrides != null) {
            release = itemReleaseOverrides.get(id);
        }
        return isUnlockedDate(release, selected);
    }

    public static boolean isMonsterUnlocked(int id, Date selected) throws java.text.ParseException {
        return isUnlocked(monsterDefinition == null ? null : monsterDefinition.get(id), selected);
    }

    public static boolean isMonsterUnlocked(int id, String visibleName, Date selected) throws java.text.ParseException {
        EntityDefinition definition = monsterDefinition == null ? null : monsterDefinition.get(id);
        if (isUnlocked(definition, selected)) return true;
        if (visibleName == null || selected == null) return false;
        LocalDate earliest = earliestMonsterReleaseByName.get(normalizeName(visibleName));
        if (earliest != null) {
            LocalDate date = selected.toInstant().atZone(ZoneId.systemDefault()).toLocalDate();
            return HistoricalCutoff.isSupported(earliest) && !earliest.isAfter(date);
        }

        // The source is a monster dataset, so many ordinary non-combat NPCs have no row.
        // Preserve truly unknown names to avoid deleting legitimate legacy bankers/shopkeepers,
        // but a known definition with no verified date is fail-closed.
        return definition == null;
    }
}

package com.rewind.regionlocker;

import com.rewind.RewindConfig;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class HistoricalMinimapMaskOverlay extends Overlay
{
    private final Client client;
    private final RewindConfig config;

    @Inject
    HistoricalMinimapMaskOverlay(Client client, RewindConfig config)
    {
        this.client = client;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(Overlay.PRIORITY_HIGHEST);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.maskLockedMinimap() || client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
        {
            return null;
        }

        int widgetId = !client.isResized() ? net.runelite.api.gameval.InterfaceID.Toplevel.MINIMAP
            : client.getVarbitValue(net.runelite.api.gameval.VarbitID.RESIZABLE_STONE_ARRANGEMENT) == 1
                ? net.runelite.api.gameval.InterfaceID.ToplevelPreEoc.MINIMAP
                : net.runelite.api.gameval.InterfaceID.ToplevelOsrsStretch.MINIMAP;
        net.runelite.api.widgets.Widget minimap = client.getWidget(widgetId);
        if (minimap == null || minimap.isHidden()) return null;
        java.awt.Rectangle bounds = minimap.getBounds();
        Graphics2D copy = (Graphics2D) graphics.create();
        copy.clip(new java.awt.geom.Ellipse2D.Double(bounds.x, bounds.y, bounds.width, bounds.height));
        int radius = Math.min(104, (int) Math.ceil(Math.max(bounds.width, bounds.height)
            / (2.0 * Math.max(0.5, client.getMinimapZoom()))) + 2);
        try {
        WorldView worldView = client.getLocalPlayer().getWorldView();
        WorldPoint centre = client.getLocalPlayer().getWorldLocation();
        copy.setColor(config.shaderGrayColor());

        for (int dx = -radius; dx <= radius; dx++)
        {
            for (int dy = -radius; dy <= radius; dy++)
            {
                WorldPoint wp = new WorldPoint(centre.getX() + dx, centre.getY() + dy, centre.getPlane());
                LocalPoint local = LocalPoint.fromWorld(worldView, wp);
                if (local != null && !HistoricalRegionState.isTileUnlocked(
                    WorldPoint.fromLocalInstance(worldView.getScene(), local, worldView.getPlane())))
                {
                    drawTile(copy, worldView, wp);
                }
            }
        }

        } finally { copy.dispose(); }

        return null;
    }

    private void drawTile(Graphics2D graphics, WorldView worldView, WorldPoint wp)
    {
        LocalPoint lp = LocalPoint.fromWorld(worldView, wp);
        if (lp == null)
        {
            return;
        }

        int x = lp.getX() & -Perspective.LOCAL_TILE_SIZE;
        int y = lp.getY() & -Perspective.LOCAL_TILE_SIZE;
        int id = worldView.getId();

        Point p1 = Perspective.localToMinimap(client, new LocalPoint(x, y, id), 30000);
        Point p2 = Perspective.localToMinimap(client, new LocalPoint(x, y + Perspective.LOCAL_TILE_SIZE, id), 30000);
        Point p3 = Perspective.localToMinimap(client, new LocalPoint(x + Perspective.LOCAL_TILE_SIZE, y + Perspective.LOCAL_TILE_SIZE, id), 30000);
        Point p4 = Perspective.localToMinimap(client, new LocalPoint(x + Perspective.LOCAL_TILE_SIZE, y, id), 30000);

        if (p1 == null || p2 == null || p3 == null || p4 == null)
        {
            return;
        }

        graphics.fillPolygon(new Polygon(
            new int[]{p1.getX(), p2.getX(), p3.getX(), p4.getX()},
            new int[]{p1.getY(), p2.getY(), p3.getY(), p4.getY()},
            4
        ));
    }
}

package com.rewind.regionlocker;

import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.input.MouseAdapter;

/**
 * Prevents the minimap from bypassing Rewind's historical region boundary.
 *
 * RuneLite's ordinary scene walking is exposed as a WALK menu action, but the
 * minimap takes a separate input path. Rather than reimplement Jagex's minimap
 * rotation/zoom math, this listener projects nearby tiles using RuneLite's own
 * Perspective.localToMinimap method and consumes clicks whose nearest tile is
 * historically locked.
 */
public class HistoricalMinimapInputBlocker extends MouseAdapter
{
    private static final int MAX_SEARCH_RADIUS_TILES = 104;
    private static final int MAX_NEAREST_DISTANCE_SQ = 64; // 8 px

    private final Client client;
    private boolean blockClickSequence;
    // Published by the client thread; mouse callbacks must never read live widgets/varbits.
    private volatile Snapshot snapshot;

    static final class TilePoint
    {
        final int x, y;
        final boolean locked;

        TilePoint(int x, int y, boolean locked)
        {
            this.x = x;
            this.y = y;
            this.locked = locked;
        }
    }

    static final class Snapshot
    {
        final Rectangle bounds;
        final TilePoint[] tiles;

        Snapshot(Rectangle bounds, TilePoint[] tiles)
        {
            this.bounds = new Rectangle(bounds);
            this.tiles = tiles.clone();
        }

        boolean shouldBlock(int x, int y)
        {
            if (!bounds.contains(x, y) || !insideMinimapCircle(bounds, x, y)) return false;
            int bestDistanceSq = Integer.MAX_VALUE;
            boolean locked = false;
            for (TilePoint tile : tiles)
            {
                int dx = tile.x - x;
                int dy = tile.y - y;
                int distanceSq = dx * dx + dy * dy;
                if (distanceSq < bestDistanceSq)
                {
                    bestDistanceSq = distanceSq;
                    locked = tile.locked;
                }
            }
            return bestDistanceSq <= MAX_NEAREST_DISTANCE_SQ && locked;
        }
    }

    public void clear()
    {
        snapshot = null;
    }

    void publish(Snapshot next)
    {
        snapshot = next;
    }

    @Inject
    HistoricalMinimapInputBlocker(Client client)
    {
        this.client = client;
    }

    @Override
    public MouseEvent mousePressed(MouseEvent event)
    {
        blockClickSequence = shouldBlock(event);
        if (blockClickSequence)
        {
            event.consume();
        }
        return event;
    }

    @Override
    public MouseEvent mouseReleased(MouseEvent event)
    {
        if (blockClickSequence && SwingUtilities.isLeftMouseButton(event))
        {
            event.consume();
        }
        return event;
    }

    @Override
    public MouseEvent mouseClicked(MouseEvent event)
    {
        if (blockClickSequence && SwingUtilities.isLeftMouseButton(event))
        {
            event.consume();
            blockClickSequence = false;
        }
        return event;
    }

    private boolean shouldBlock(MouseEvent event)
    {
        Snapshot current = snapshot;
        return !event.isConsumed() && SwingUtilities.isLeftMouseButton(event)
            && current != null && current.shouldBlock(event.getX(), event.getY());
    }

    /** Called on the client thread once per tick, never from an AWT callback. */
    public void refresh()
    {
        if (client.getGameState() != GameState.LOGGED_IN || client.isMenuOpen())
        {
            clear();
            return;
        }

        Widget minimap = getMinimapWidget();
        Player player = client.getLocalPlayer();
        if (minimap == null || minimap.isHidden() || player == null)
        {
            clear();
            return;
        }

        Rectangle bounds = minimap.getBounds();
        WorldView worldView = player.getWorldView();
        LocalPoint playerLocal = player.getLocalLocation();
        if (worldView == null || playerLocal == null)
        {
            clear();
            return;
        }

        int centreSceneX = playerLocal.getSceneX();
        int centreSceneY = playerLocal.getSceneY();
        int searchRadius = Math.min(MAX_SEARCH_RADIUS_TILES, (int) Math.ceil(
            Math.max(bounds.width, bounds.height) / (2.0 * Math.max(0.5, client.getMinimapZoom()))) + 3);
        List<TilePoint> tiles = new ArrayList<>();

        int minX = Math.max(0, centreSceneX - searchRadius);
        int maxX = Math.min(worldView.getSizeX() - 1, centreSceneX + searchRadius);
        int minY = Math.max(0, centreSceneY - searchRadius);
        int maxY = Math.min(worldView.getSizeY() - 1, centreSceneY + searchRadius);

        for (int sceneX = minX; sceneX <= maxX; sceneX++)
        {
            for (int sceneY = minY; sceneY <= maxY; sceneY++)
            {
                LocalPoint candidate = LocalPoint.fromScene(sceneX, sceneY, worldView);
                Point projected = Perspective.localToMinimap(client, candidate, 30000);
                if (projected == null)
                {
                    continue;
                }

                WorldPoint worldPoint = WorldPoint.fromLocalInstance(
                    worldView.getScene(), candidate, worldView.getPlane());
                tiles.add(new TilePoint(projected.getX(), projected.getY(),
                    !HistoricalRegionState.isTileUnlocked(worldPoint)));
            }
        }

        publish(new Snapshot(bounds, tiles.toArray(new TilePoint[0])));
    }

    private Widget getMinimapWidget()
    {
        int widgetId = !client.isResized() ? InterfaceID.Toplevel.MINIMAP
            : client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT) == 1
                ? InterfaceID.ToplevelPreEoc.MINIMAP
                : InterfaceID.ToplevelOsrsStretch.MINIMAP;
        return client.getWidget(widgetId);
    }

    private static boolean insideMinimapCircle(Rectangle bounds, int x, int y)
    {
        double rx = Math.max(1.0, bounds.width / 2.0);
        double ry = Math.max(1.0, bounds.height / 2.0);
        double nx = (x - (bounds.x + rx)) / rx;
        double ny = (y - (bounds.y + ry)) / ry;
        return nx * nx + ny * ny <= 1.0;
    }
}

package com.rewind.regionlocker;

import com.rewind.RewindConfig;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Perspective;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class HistoricalSceneMaskOverlay extends Overlay
{
    private final Client client;
    private final RewindConfig config;

    @Inject
    HistoricalSceneMaskOverlay(Client client, RewindConfig config)
    {
        this.client = client;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
        setPriority(Overlay.PRIORITY_HIGHEST);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.maskLockedScene() || client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
        {
            return null;
        }

        WorldView worldView = client.getLocalPlayer().getWorldView();
        Graphics2D copy = (Graphics2D) graphics.create();
        copy.clip(new java.awt.Rectangle(client.getViewportXOffset(), client.getViewportYOffset(),
            client.getViewportWidth(), client.getViewportHeight()));
        copy.setColor(config.shaderGrayColor());
        try {

        for (int dx = 0; dx < worldView.getSizeX(); dx++)
        {
            for (int dy = 0; dy < worldView.getSizeY(); dy++)
            {
                LocalPoint lp = LocalPoint.fromScene(dx, dy, worldView);
                if (lp == null)
                {
                    continue;
                }

                WorldPoint template = WorldPoint.fromLocalInstance(worldView.getScene(), lp, worldView.getPlane());
                if (HistoricalRegionState.isTileUnlocked(template)) continue;
                Polygon poly = Perspective.getCanvasTilePoly(client, lp);
                if (poly != null)
                {
                    copy.fillPolygon(poly);
                }
            }
        }

        } finally { copy.dispose(); }
        return null;
    }
}

