package com.rewind.regionlocker;

import com.rewind.RewindConfig;
import com.google.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.geom.GeneralPath;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class RegionBorderOverlay extends Overlay
{
	private static final int LOCAL_TILE_SIZE = Perspective.LOCAL_TILE_SIZE;
	private static final int CHUNK_SIZE = 8;
	private static final int MAP_SQUARE_SIZE = CHUNK_SIZE * CHUNK_SIZE; // 64
	private static final int CULL_CHUNK_BORDERS_RANGE = 16;

	private final Client client;
	private final RewindConfig config;

	@Inject
	private RegionBorderOverlay(Client client, RewindConfig config)
	{
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_HIGH);
		setLayer(OverlayLayer.ABOVE_SCENE);
		this.client = client;
		this.config = config;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (config.renderRegionBorders()) renderMapSquares(graphics);

		return null;
	}

	private void renderMapSquares(Graphics2D graphics)
	{
		WorldPoint wp = client.getLocalPlayer().getWorldLocation();
		int startX = (wp.getX() - CULL_CHUNK_BORDERS_RANGE + MAP_SQUARE_SIZE - 1) / MAP_SQUARE_SIZE * MAP_SQUARE_SIZE;
		int startY = (wp.getY() - CULL_CHUNK_BORDERS_RANGE + MAP_SQUARE_SIZE - 1) / MAP_SQUARE_SIZE * MAP_SQUARE_SIZE;
		int endX = (wp.getX() + CULL_CHUNK_BORDERS_RANGE) / MAP_SQUARE_SIZE * MAP_SQUARE_SIZE;
		int endY = (wp.getY() + CULL_CHUNK_BORDERS_RANGE) / MAP_SQUARE_SIZE * MAP_SQUARE_SIZE;

		graphics.setStroke(new BasicStroke(config.regionBorderWidth()));
		Color c = config.regionBorderColor();
		graphics.setColor(c);

		GeneralPath path = new GeneralPath();
		for (int x = startX; x <= endX; x += MAP_SQUARE_SIZE)
		{
			LocalPoint lp1 = LocalPoint.fromWorld(client.getTopLevelWorldView(), x, wp.getY() - CULL_CHUNK_BORDERS_RANGE);
			LocalPoint lp2 = LocalPoint.fromWorld(client.getTopLevelWorldView(), x, wp.getY() + CULL_CHUNK_BORDERS_RANGE);

			boolean first = true;
			for (int y = lp1.getY(); y <= lp2.getY(); y += LOCAL_TILE_SIZE)
			{
				Point p = Perspective.localToCanvas(client,
						new LocalPoint(lp1.getX() - LOCAL_TILE_SIZE / 2, y - LOCAL_TILE_SIZE / 2, client.getTopLevelWorldView().getId()),
						client.getTopLevelWorldView().getPlane());
				if (p != null)
				{
					if (first)
					{
						path.moveTo(p.getX(), p.getY());
						first = false;
					}
					else
					{
						path.lineTo(p.getX(), p.getY());
					}
				}
			}
		}
		for (int y = startY; y <= endY; y += MAP_SQUARE_SIZE)
		{
			LocalPoint lp1 = LocalPoint.fromWorld(client.getTopLevelWorldView(), wp.getX() - CULL_CHUNK_BORDERS_RANGE, y);
			LocalPoint lp2 = LocalPoint.fromWorld(client.getTopLevelWorldView(), wp.getX() + CULL_CHUNK_BORDERS_RANGE, y);

			boolean first = true;
			for (int x = lp1.getX(); x <= lp2.getX(); x += LOCAL_TILE_SIZE)
			{
				Point p = Perspective.localToCanvas(client,
						new LocalPoint(x - LOCAL_TILE_SIZE / 2, lp1.getY() - LOCAL_TILE_SIZE / 2, client.getTopLevelWorldView().getId()),
						client.getTopLevelWorldView().getPlane());
				if (p != null)
				{
					if (first)
					{
						path.moveTo(p.getX(), p.getY());
						first = false;
					}
					else
					{
						path.lineTo(p.getX(), p.getY());
					}
				}
			}
		}
		graphics.draw(path);
	}
}

package com.rewind;

import lombok.Getter;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InterfaceID;

public enum RewindSkill {
    ATTACK(Skill.ATTACK, InterfaceID.Stats.ATTACK),
    STRENGTH(Skill.STRENGTH, InterfaceID.Stats.STRENGTH),
    DEFENCE(Skill.DEFENCE, InterfaceID.Stats.DEFENCE),
    RANGED(Skill.RANGED, InterfaceID.Stats.RANGED),
    PRAYER(Skill.PRAYER, InterfaceID.Stats.PRAYER),
    MAGIC(Skill.MAGIC, InterfaceID.Stats.MAGIC),
    RUNECRAFT(Skill.RUNECRAFT, InterfaceID.Stats.RUNECRAFT),
    CONSTRUCTION(Skill.CONSTRUCTION, InterfaceID.Stats.CONSTRUCTION),
    HITPOINTS(Skill.HITPOINTS, InterfaceID.Stats.HITPOINTS),
    AGILITY(Skill.AGILITY, InterfaceID.Stats.AGILITY),
    HERBLORE(Skill.HERBLORE, InterfaceID.Stats.HERBLORE),
    THIEVING(Skill.THIEVING, InterfaceID.Stats.THIEVING),
    CRAFTING(Skill.CRAFTING, InterfaceID.Stats.CRAFTING),
    FLETCHING(Skill.FLETCHING, InterfaceID.Stats.FLETCHING),
    SLAYER(Skill.SLAYER, InterfaceID.Stats.SLAYER),
    HUNTER(Skill.HUNTER, InterfaceID.Stats.HUNTER),
    MINING(Skill.MINING, InterfaceID.Stats.MINING),
    SMITHING(Skill.SMITHING, InterfaceID.Stats.SMITHING),
    FISHING(Skill.FISHING, InterfaceID.Stats.FISHING),
    COOKING(Skill.COOKING, InterfaceID.Stats.COOKING),
    FIREMAKING(Skill.FIREMAKING, InterfaceID.Stats.FIREMAKING),
    WOODCUTTING(Skill.WOODCUTTING, InterfaceID.Stats.WOODCUTTING),
    FARMING(Skill.FARMING, InterfaceID.Stats.FARMING),
    SAILING(Skill.SAILING, InterfaceID.Stats.SAILING);

    @Getter
    private Skill skill;
    @Getter
    private int widgetID;

    RewindSkill(Skill skill, int id) {
        this.skill = skill;
        this.widgetID = id;
    }
}

package com.rewind;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Hides historically unavailable skills from the Stats tab entirely.
 * A skill reappears normally once it is available at the selected release.
 */
public class RewindSkillOverlay extends Overlay
{
    private final Client client;
    private final RewindPlugin plugin;

    @Inject
    RewindSkillOverlay(Client client, RewindPlugin plugin)
    {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (client.getGameState() != GameState.LOGGED_IN || plugin.getCurrentRelease() == null)
        {
            return null;
        }

        Widget stats = client.getWidget(InterfaceID.Stats.UNIVERSE);
        if (stats == null || stats.isHidden())
        {
            return null;
        }

        List<Skill> unlocked = Release.getSkills(plugin.getCurrentRelease());
        updateSkillWidgets(stats.getStaticChildren(), unlocked);
        updateSkillWidgets(stats.getDynamicChildren(), unlocked);
        return null;
    }

    void restoreAllSkills()
    {
        Widget stats = client.getWidget(InterfaceID.Stats.UNIVERSE);
        if (stats == null)
        {
            return;
        }

        restoreSkillWidgets(stats.getStaticChildren());
        restoreSkillWidgets(stats.getDynamicChildren());
    }

    private static void updateSkillWidgets(Widget[] widgets, List<Skill> unlocked)
    {
        if (widgets == null)
        {
            return;
        }

        for (Widget widget : widgets)
        {
            if (widget == null)
            {
                continue;
            }

            Skill skill = skillForWidget(widget);
            if (skill == null)
            {
                continue;
            }

            boolean locked = HistoricalPermanentExclusions.isSkillPermanentlyLocked(skill)
                || !unlocked.contains(skill);
            widget.setHidden(locked);
        }
    }

    private static void restoreSkillWidgets(Widget[] widgets)
    {
        if (widgets == null)
        {
            return;
        }

        for (Widget widget : widgets)
        {
            if (widget != null && skillForWidget(widget) != null)
            {
                widget.setHidden(false);
            }
        }
    }

    static Skill skillForWidget(Widget widget)
    {
        String[] actions = widget.getActions();
        if (actions == null)
        {
            return null;
        }

        for (String action : actions)
        {
            if (action == null)
            {
                continue;
            }

            String value = action.replaceAll("<[^>]*>", "").trim();
            if (!value.regionMatches(true, 0, "View ", 0, 5)
                || !value.toLowerCase(java.util.Locale.ROOT).endsWith(" guide"))
            {
                continue;
            }

            String skillName = value.substring(5, value.length() - 6).trim();
            for (RewindSkill rewindSkill : RewindSkill.values())
            {
                if (rewindSkill.getSkill().getName().equalsIgnoreCase(skillName))
                {
                    return rewindSkill.getSkill();
                }
            }
        }

        return null;
    }
}
